"""
JobAgent - desktop app.
Runs the search -> score -> tailor cycle in the background on a schedule.
Applying opens your Chrome with the form pre-filled; you press Submit.
"""
import base64, io, json, math, os, queue, sys, threading, time, webbrowser
from datetime import datetime, timezone
from pathlib import Path
import tkinter as tk
from tkinter import filedialog, messagebox
import customtkinter as ctk
from PIL import Image, ImageDraw, ImageFont, ImageTk

APP_DIR = Path(os.environ.get("APPDATA", Path.home())) / "JobAgent"
APP_DIR.mkdir(parents=True, exist_ok=True)
os.environ["JOB_AGENT_HOME"] = str(APP_DIR)  # must be set before importing job_agent
CONFIG = APP_DIR / "config.json"
LOGFILE = APP_DIR / "agent.log"

import job_agent as ja  # noqa: E402

DEFAULTS = {"api_key": "", "location": "", "min_score": 60, "max_jobs": 10, "interval_h": 6,
            "autostart": False, "username": "", "cv_file": ""}

# ---------------- colors ----------------
BLUE, BAND = "#0A3BA6", "#0B44B2"
PAGE, WHITE, NAVY, GRAY = "#F4EFF1", "#FFFFFF", "#0B1F4B", "#7A7F90"
PURPLE, PURPLE_T, DKBLUE, HEADER = "#6B35E8", "#7B3FE4", "#0A2F9E", "#00134A"
G1, G2 = (123, 63, 228), (91, 202, 220)          # purple -> cyan
NAV1, NAV2 = (124, 58, 237), (80, 200, 215)
FAM = "Segoe UI"
SIDEBAR_W, BAND_H = 197, 37

EMBEDDED = {
    "logo": "",
    "gear": "",
}


def load_asset(path):
    return Image.open(io.BytesIO(base64.b64decode(EMBEDDED[Path(path).stem])))


def load_cfg():
    cfg = dict(DEFAULTS)
    if CONFIG.exists():
        cfg.update(json.loads(CONFIG.read_text(encoding="utf-8")))
    return cfg


# ---------------- image helpers ----------------
def pil_font(size, bold=False):
    names = ["segoeuib.ttf", "arialbd.ttf", "DejaVuSans-Bold.ttf"] if bold else ["segoeui.ttf", "arial.ttf", "DejaVuSans.ttf"]
    for n in names:
        try:
            return ImageFont.truetype(n, size)
        except OSError:
            pass
    return ImageFont.load_default()


def lerp(c1, c2, t): return tuple(int(c1[i] + (c2[i] - c1[i]) * t) for i in range(3))


def hgrad(w, h, c1, c2):
    strip = Image.new("RGBA", (256, 1))
    strip.putdata([lerp(c1, c2, i / 255) + (255,) for i in range(256)])
    return strip.resize((w, h), Image.BILINEAR)


_cache = {}


def cimg(im, w, h):
    return ctk.CTkImage(light_image=im, dark_image=im, size=(w, h))


def box_img(text, w, h, radius, c1=None, c2=None, fill=None, color=(255, 255, 255), size=14, bold=False, align="center", pad=16):
    """Rounded rectangle (gradient or flat) with text; transparent when no fill and no gradient."""
    key = ("box", text, w, h, radius, c1, c2, fill, color, size, bold, align, pad)
    if key in _cache: return _cache[key]
    k = 3; W, H = w * k, h * k
    im = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    if c1:
        mask = Image.new("L", (W, H), 0)
        ImageDraw.Draw(mask).rounded_rectangle((0, 0, W - 1, H - 1), radius=radius * k, fill=255)
        im.paste(hgrad(W, H, c1, c2 or c1), (0, 0), mask)
    elif fill:
        ImageDraw.Draw(im).rounded_rectangle((0, 0, W - 1, H - 1), radius=radius * k, fill=fill)
    if text:
        f = pil_font(size * k, bold)
        if align == "center": ImageDraw.Draw(im).text((W / 2, H / 2), text, font=f, fill=color, anchor="mm")
        else: ImageDraw.Draw(im).text((pad * k, H / 2), text, font=f, fill=color, anchor="lm")
    _cache[key] = cimg(im, w, h)
    return _cache[key]


def gtext(text, px, c1=G1, c2=G2):
    """Gradient-filled text (stat numbers in the cards)."""
    key = ("gt", text, px)
    if key in _cache: return _cache[key]
    k = 3; f = pil_font(px * k, True)
    l, t, r, b = f.getbbox(text)
    W, H = int(r + 6 * k), int(px * k * 1.35)
    mask = Image.new("L", (W, H), 0); ImageDraw.Draw(mask).text((2 * k, 0), text, font=f, fill=255)
    im = Image.new("RGBA", (W, H), (0, 0, 0, 0)); im.paste(hgrad(W, H, c1, c2), (0, 0), mask)
    _cache[key] = cimg(im, W // k, H // k)
    return _cache[key]


def wave_img(w, h, radius=14):
    key = ("wave", w, h)
    if key in _cache: return _cache[key]
    k = 3; W, H = w * k, h * k
    mask = Image.new("L", (W, H), 0); md = ImageDraw.Draw(mask)
    pts = [(x, (0.20 + 0.34 * math.sin(math.pi * x / W)) * H) for x in range(0, W + 1, 4)]
    md.polygon(pts + [(W, H), (0, H)], fill=255)
    rr = Image.new("L", (W, H), 0); ImageDraw.Draw(rr).rounded_rectangle((0, -H, W - 1, H - 1), radius=radius * k, fill=255)
    from PIL import ImageChops
    mask = ImageChops.multiply(mask, rr)
    im = Image.new("RGBA", (W, H), (0, 0, 0, 0)); im.paste(hgrad(W, H, G1, G2), (0, 0), mask)
    _cache[key] = cimg(im, w, h)
    return _cache[key]


def click_label(parent, image, cmd, **kw):
    """An image that acts as a button (CTkLabel + click binding)."""
    lab = ctk.CTkLabel(parent, text="", image=image, cursor="hand2", **kw)
    lab.bind("<Button-1>", lambda e: cmd())
    return lab


def toggle_img():
    k = 3; S = 30 * k
    im = Image.new("RGBA", (S, S), (0, 0, 0, 0)); d = ImageDraw.Draw(im)
    d.rounded_rectangle((0, 0, S - 1, S - 1), radius=8 * k, fill=(19, 21, 73, 255))
    d.rounded_rectangle((0, 0, S // 2, S - 1), radius=8 * k, fill=(0, 0, 0, 255))
    d.rectangle((S // 4, 0, S // 2, S - 1), fill=(0, 0, 0, 255))
    d.rounded_rectangle((0, 0, S - 1, S - 1), radius=8 * k, outline=(40, 60, 140, 255), width=k)
    return cimg(im, 30, 30)


def rel_time(v):
    try:
        if isinstance(v, (int, float)): dt = datetime.fromtimestamp(v, timezone.utc)
        else: dt = datetime.fromisoformat(str(v).replace("Z", "+00:00"))
        if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)
        s = (datetime.now(timezone.utc) - dt).total_seconds()
    except Exception:
        return "recently"
    if s < 3600: return "just now" if s < 120 else f"{int(s // 60)} min ago"
    if s < 86400: h = int(s // 3600); return f"{h} hour{'s' if h > 1 else ''} ago"
    d = int(s // 86400)
    if d < 7: return f"{d} day{'s' if d > 1 else ''} ago"
    w = d // 7
    return f"{w} week{'s' if w > 1 else ''} ago" if d < 60 else f"{d // 30} months ago"


def classify(text, min_score=60):
    """Turn a raw log line into (LEVEL, message)."""
    t = text.strip(); low = t.lower()
    if t.startswith("!"):
        t = t.lstrip("! ").strip(); low = t.lower()
        if any(k in low for k in ("rate", "unavailable", "trying next", "quota", "429")): return "WARN", t
        return "ERROR", t
    if t.startswith("✔"): return "SUCCESS", t.lstrip("✔ ")
    if "failed" in low: return "ERROR", t
    if low.startswith(("saved", "pre-filled", "settings saved")) or "jobs ready" in low: return "SUCCESS", t
    if t.startswith("[") and "]" in t and t[1:t.index("]")].strip().isdigit():
        return ("SUCCESS" if int(t[1:t.index("]")]) >= min_score else "INFO"), t
    if "approaching" in low or "retry" in low: return "WARN", t
    return "INFO", t


class QueueWriter:
    def __init__(self, q): self.q = q
    def write(self, s):
        if s.strip(): self.q.put(("log", s.rstrip()))
    def flush(self): pass


# ====================================================================
class App(ctk.CTk):
    def __init__(self, minimized=False):
        super().__init__(fg_color=BLUE)
        self.title("JobAgent")
        self.geometry("1280x720")
        self.minsize(1000, 600)
        try:
            self._icon = ImageTk.PhotoImage(load_asset("logo").resize((64, 64)))
            self.iconphoto(False, self._icon)
        except Exception:
            pass
        self.cfg = load_cfg()
        self.q = queue.Queue()
        self.stop_evt = threading.Event()
        self.worker = None
        self.cycle_lock = threading.Lock()
        self.side_open = True
        self.animating = False
        self.show_all = False
        self.state_text = "Stopped"
        self._jobs_sig = None
        self.current = "HOME"
        sys.stdout = QueueWriter(self.q)
        sys.stderr = QueueWriter(self.q)

        self.grid_columnconfigure(1, weight=1)
        self.grid_rowconfigure(1, weight=1)
        self.build_sidebar()
        self.build_band()
        self.main = ctk.CTkFrame(self, fg_color=PAGE, corner_radius=0)
        self.main.grid(row=1, column=1, sticky="nsew")
        self.main.grid_columnconfigure(0, weight=1); self.main.grid_rowconfigure(0, weight=1)
        self.pages = {"HOME": self.build_home(), "LOG": self.build_log(), "SETTINGS": self.build_settings()}
        self.show("HOME")
        self.load_log_history()
        self.apply_key()
        self.refresh_all()
        self.after(200, self.poll)
        if minimized:
            self.iconify()
            if self.cfg["api_key"] and ja.PROFILE_PATH.exists():
                self.start_agent()
        elif not self.cfg["username"]:
            self.after(500, self.show_login)

    # ================= frame pieces =================
    def build_sidebar(self):
        self.side = ctk.CTkFrame(self, width=SIDEBAR_W, fg_color=BLUE, corner_radius=0)
        self.side.grid(row=0, column=0, rowspan=2, sticky="ns")
        self.side.grid_propagate(False)
        f = load_asset("logo")
        fw, fh = int(f.width * 58 / f.height), 58
        ctk.CTkLabel(self.side, image=cimg(f, fw, fh), text="").place(x=22, y=9)
        ctk.CTkLabel(self.side, text="JobAgent", font=ctk.CTkFont(FAM, 22, "bold"), text_color="white").place(x=66, y=39, anchor="w")
        self.nav = {}
        for name, label, y in (("HOME", "Home", 89), ("LOG", "Log", 157)):
            lab = click_label(self.side, box_img(label, 166, 53, 9, size=15, align="left", pad=15), lambda n=name: self.show(n))
            lab.place(x=15, y=y); self.nav[name] = (lab, label)
        self.user_btn = click_label(self.side, box_img("UserName", 123, 44, 10, NAV1, NAV2, size=14, bold=True, align="left", pad=18),
                                    lambda: self.show("SETTINGS"))
        self.user_btn.place(x=12, rely=1.0, y=-19, anchor="sw")
        self.set_username(self.cfg["username"])
        self.gear = click_label(self.side, cimg(load_asset("gear"), 46, 45), lambda: self.show("SETTINGS"))
        self.gear.place(x=141, rely=1.0, y=-18, anchor="sw")

    def set_username(self, name):
        self.user_btn.configure(image=box_img(name or "UserName", 123, 44, 10, NAV1, NAV2, size=14, bold=True, align="left", pad=18))

    def build_band(self):
        self.band = ctk.CTkFrame(self, height=BAND_H, fg_color=BAND, corner_radius=0)
        self.band.grid(row=0, column=1, sticky="ew")
        self.band.grid_propagate(False)
        self.btn_toggle = ctk.CTkButton(self.band, image=toggle_img(), text="", width=30, height=30, fg_color="transparent",
                                        hover=False, border_width=0, corner_radius=0, command=self.toggle_sidebar)
        self.btn_toggle.place(x=10, y=4)

    def toggle_sidebar(self):
        page = self.pages[self.current]
        page.grid_remove()                    # nothing to re-layout while the width changes
        if self.side_open:
            self.side.grid_remove()
        else:
            self.side.grid(row=0, column=0, rowspan=2, sticky="ns")
        self.side_open = not self.side_open
        self.update_idletasks()
        self.after(15, lambda: page.grid(row=0, column=0, sticky="nsew"))

    def show(self, name):
        self.current = name
        for f in self.pages.values(): f.grid_remove()
        self.pages[name].grid(row=0, column=0, sticky="nsew")
        for n, (b, label) in self.nav.items():
            on = n == name
            b.configure(image=box_img(label, 166, 53, 9, NAV1 if on else None, NAV2 if on else None, size=15,
                                      bold=False, align="left", pad=15))

    def head(self, parent, title, sub):
        h = ctk.CTkFrame(parent, fg_color="transparent")
        ctk.CTkLabel(h, text=title, font=ctk.CTkFont(FAM, 34, "bold"), text_color=NAVY).pack(anchor="w")
        ctk.CTkLabel(h, text=sub, font=ctk.CTkFont(FAM, 15), text_color=GRAY).pack(anchor="w")
        return h

    def card(self, parent, **kw):
        return ctk.CTkFrame(parent, fg_color=WHITE, corner_radius=14, border_width=1, border_color="#EDE7EA", **kw)

    def sbtn(self, parent, text, w, h, cmd, fill=PURPLE, size=12, hover=None):
        return ctk.CTkButton(parent, text=text, width=w, height=h, corner_radius=7, fg_color=fill,
                             hover_color=hover or fill, text_color="white", font=ctk.CTkFont(FAM, size, "bold"), command=cmd)

    # ================= HOME =================
    def build_home(self):
        f = ctk.CTkFrame(self.main, fg_color="transparent")
        f.grid_columnconfigure((0, 1, 2, 3), weight=1, uniform="card"); f.grid_rowconfigure(2, weight=1)
        self.head(f, "Home", "Your job search overview at a glance").grid(row=0, column=0, columnspan=4, sticky="w", padx=32, pady=(18, 14))
        self.cards = {}
        specs = (("status", "STATUS"), ("cv", "CV PROFILE"), ("matched", "MATCHED JOBS"), ("apps", "APPLICATIONS"))
        for i, (key, title) in enumerate(specs):
            c = self.card(f, height=167); c.grid(row=1, column=i, sticky="ew", padx=(32 if i == 0 else 11, 32 if i == 3 else 11))
            c.grid_propagate(False)
            wave = ctk.CTkLabel(c, text="", image=wave_img(220, 40)); wave.place(x=0, rely=1.0, y=-1, anchor="sw")
            ctk.CTkLabel(c, text=title, font=ctk.CTkFont(FAM, 12, "bold"), text_color=NAVY).place(x=16, y=14)
            val = ctk.CTkLabel(c, text="", image=gtext("0", 38)); val.place(x=14, y=40)
            sub = ctk.CTkLabel(c, text="", font=ctk.CTkFont(FAM, 13), text_color="#3E4560"); sub.place(x=16, y=96)
            c.bind("<Configure>", lambda e, c=c, w=wave: self.fit_wave(c, w))
            self.cards[key] = (val, sub)
        self.btn_run = self.sbtn(self.cards_frame_parent(f, 0), "Start", 62, 26, self.toggle_agent, PURPLE, 12)
        self.btn_run.place(relx=1.0, x=-14, y=12, anchor="ne")
        self.btn_cv = self.sbtn(self.cards_frame_parent(f, 1), "Load CV", 70, 26, self.load_cv, PURPLE, 12)
        self.btn_cv.place(relx=1.0, x=-14, y=12, anchor="ne")

        t = self.card(f); t.grid(row=2, column=0, columnspan=4, sticky="nsew", padx=32, pady=(18, 22))
        t.grid_columnconfigure(0, weight=1); t.grid_rowconfigure(1, weight=1)
        ctk.CTkLabel(t, text="Matched Jobs", font=ctk.CTkFont(FAM, 18, "bold"), text_color=NAVY).grid(row=0, column=0, sticky="w", padx=18, pady=(14, 8))
        self.rows = ctk.CTkScrollableFrame(t, fg_color=WHITE, corner_radius=0, scrollbar_button_color="#E2DBE6",
                                           scrollbar_button_hover_color="#CFC6D6")
        self.rows.grid(row=1, column=0, sticky="nsew", padx=(14, 6), pady=(0, 4))
        self.rows.grid_columnconfigure(0, weight=1)
        self.link = ctk.CTkButton(t, text="View all matched jobs", fg_color="transparent", hover=False, text_color=PURPLE_T,
                                  font=ctk.CTkFont(FAM, 14), height=26, command=self.toggle_all)
        self.link.grid(row=2, column=0, pady=(0, 8))
        return f

    def cards_frame_parent(self, f, i):
        return [w for w in f.grid_slaves(row=1, column=i)][0]

    def fit_wave(self, card, label):
        if getattr(label, "_pending", None): self.after_cancel(label._pending)
        label._pending = self.after(150, lambda: self._do_wave(card, label))

    def _do_wave(self, card, label):
        label._pending = None
        w = max(60, int(card.winfo_width() / self._get_window_scaling()))
        if getattr(label, "_fit_w", None) != w:
            label._fit_w = w; label.configure(image=wave_img(w, 40))

    COLS = (("JOB TITLE", 30), ("COMPANY", 26), ("MATCH", 11), ("LOCATION", 20), ("POSTED", 17), ("ACTIONS", 22))

    def table_row(self, parent, r, values, header=False, job=None):
        row = ctk.CTkFrame(parent, fg_color=HEADER if header else WHITE, corner_radius=5 if header else 0, height=34 if header else 40)
        row.grid(row=r, column=0, sticky="ew", pady=(0, 0)); row.grid_propagate(False)
        for i, (_, w) in enumerate(self.COLS): row.grid_columnconfigure(i, weight=w, uniform="tc")
        if header:
            px = -max(10, int(11 * self._get_window_scaling()))
            for i, (name, _) in enumerate(self.COLS):
                tk.Label(row, text=name, font=(FAM, px, "bold"), fg="white", bg=HEADER, bd=0, highlightthickness=0).grid(
                    row=0, column=i, sticky="w" if i < 5 else "", padx=(14, 4), pady=6)
            return row
        title, company, match, loc, posted = values
        st = job.get("status", "ready")
        dim = st in ("applied",)
        lab = lambda t, i, color=NAVY, bold=False, cmd=None: ctk.CTkLabel(
            row, text=t, anchor="w", text_color=color, font=ctk.CTkFont(FAM, 13, "bold" if bold else "normal")).grid(row=0, column=i, sticky="w", padx=(14, 4))
        lab(title + ("  (applied)" if st == "applied" else ""), 0, GRAY if dim else NAVY)
        lab(company, 1); lab(match, 2, PURPLE_T, True); lab(loc, 3); lab(posted, 4)
        box = ctk.CTkFrame(row, fg_color="transparent"); box.grid(row=0, column=5)
        self.sbtn(box, "View", 58, 26, lambda j=job: self.view_job(j), PURPLE).pack(side="left", padx=4)
        saved = st == "saved"
        self.sbtn(box, "Saved" if saved else "Save", 58, 26, lambda j=job: self.toggle_save(j), "#3B8F5A" if saved else DKBLUE).pack(side="left", padx=4)
        return row

    def render_rows(self):
        jobs = [j for j in self.jobs() if j.get("status") != "skipped"]
        jobs.sort(key=lambda x: -x.get("score", 0))
        shown = jobs if self.show_all else jobs[:5]
        sig = (json.dumps(shown, sort_keys=True, default=str), self.show_all)
        if sig == self._jobs_sig: return
        self._jobs_sig = sig
        for w in self.rows.winfo_children(): w.destroy()
        self.table_row(self.rows, 0, None, header=True)
        if not shown:
            ctk.CTkLabel(self.rows, text="No matched jobs yet.\nLoad your CV and press Start.", font=ctk.CTkFont(FAM, 14),
                         text_color=GRAY, justify="center").grid(row=1, column=0, pady=40)
        for i, j in enumerate(shown[:150]):
            self.table_row(self.rows, 1 + 2 * i, (j["title"], j["company"], f"{j.get('score', 0)}%", j["location"], rel_time(j.get("posted"))), job=j)
            ctk.CTkFrame(self.rows, height=1, fg_color="#EEE9EC", corner_radius=0).grid(row=2 + 2 * i, column=0, sticky="ew")
        self.link.configure(text=("Show fewer" if self.show_all else "View all matched jobs") if len(jobs) > 5 else "")

    def toggle_all(self):
        self.show_all = not self.show_all
        self.render_rows()

    # ================= LOG =================
    def build_log(self):
        f = ctk.CTkFrame(self.main, fg_color="transparent")
        f.grid_columnconfigure(0, weight=1); f.grid_rowconfigure(1, weight=1)
        self.head(f, "Log", "System activity and events in real time").grid(row=0, column=0, sticky="w", padx=32, pady=(18, 14))
        panel = ctk.CTkFrame(f, fg_color="#10123A", corner_radius=14)
        panel.grid(row=1, column=0, sticky="nsew", padx=32, pady=(0, 22))
        panel.grid_columnconfigure(0, weight=1); panel.grid_rowconfigure(1, weight=1)
        ctk.CTkLabel(panel, text="System Log", font=ctk.CTkFont(FAM, 17, "bold"), text_color="white").grid(row=0, column=0, sticky="w", padx=22, pady=(16, 6))
        bar = ctk.CTkFrame(panel, fg_color="transparent"); bar.grid(row=0, column=0, sticky="e", padx=18, pady=(14, 4))
        self.sbtn(bar, "Copy", 88, 34, self.copy_log, PURPLE, 13).pack(side="left", padx=5)
        self.sbtn(bar, "Clear", 88, 34, self.clear_log, DKBLUE, 13).pack(side="left", padx=5)
        self.logbox = ctk.CTkTextbox(panel, fg_color="#10123A", text_color="#FFFFFF", font=("Consolas", 13), wrap="word",
                                     state="disabled", corner_radius=0, spacing1=5)
        self.logbox.grid(row=1, column=0, sticky="nsew", padx=(18, 8), pady=(4, 14))
        for tag, color in (("ts", "#6C9AD6"), ("INFO", "#4ADE80"), ("SUCCESS", "#22A6E0"), ("WARN", "#F0B43C"), ("ERROR", "#F0476F")):
            self.logbox.tag_config(tag, foreground=color)
        return f

    def log_line(self, ts, level, msg):
        self.logbox.configure(state="normal")
        self.logbox.insert("end", f"[{ts}]  ", "ts")
        self.logbox.insert("end", f"{level:<9}", level)
        self.logbox.insert("end", msg + "\n")
        self.logbox.see("end"); self.logbox.configure(state="disabled")

    def add_log(self, text):
        level, msg = classify(text, int(self.cfg["min_score"]))
        ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.log_line(ts, level, msg)
        try:
            with open(LOGFILE, "a", encoding="utf-8") as fh: fh.write(f"{ts}|{level}|{msg}\n")
        except OSError:
            pass

    def load_log_history(self):
        try:
            for line in LOGFILE.read_text(encoding="utf-8").splitlines()[-300:]:
                ts, level, msg = line.split("|", 2)
                self.log_line(ts, level, msg)
        except (OSError, ValueError):
            pass

    def clear_log(self):
        self.logbox.configure(state="normal"); self.logbox.delete("1.0", "end"); self.logbox.configure(state="disabled")
        try: LOGFILE.write_text("", encoding="utf-8")
        except OSError: pass

    def copy_log(self):
        self.clipboard_clear(); self.clipboard_append(self.logbox.get("1.0", "end"))

    # ================= SETTINGS =================
    INTERVALS = {"Every hour": 1, "Every 3 hours": 3, "Every 6 hours": 6, "Every 12 hours": 12, "Every 24 hours": 24}

    def build_settings(self):
        f = ctk.CTkFrame(self.main, fg_color="transparent")
        f.grid_columnconfigure(0, weight=1); f.grid_rowconfigure(1, weight=1)
        self.head(f, "Settings", "Manage your preferences and the job search").grid(row=0, column=0, sticky="w", padx=32, pady=(18, 14))
        card = self.card(f); card.grid(row=1, column=0, sticky="nsew", padx=32, pady=(0, 22))
        card.grid_columnconfigure(0, weight=1); card.grid_rowconfigure(0, weight=1)
        sc = ctk.CTkScrollableFrame(card, fg_color=WHITE, corner_radius=0, scrollbar_button_color="#E2DBE6")
        sc.grid(row=0, column=0, sticky="nsew", padx=(10, 4), pady=(10, 0)); sc.grid_columnconfigure(0, weight=1)
        v = self.vars = {
            "username": tk.StringVar(value=self.cfg["username"]), "api_key": tk.StringVar(value=self.cfg["api_key"]),
            "location": tk.StringVar(value=self.cfg["location"] or "Anywhere"),
            "interval": tk.StringVar(), "min_score": tk.StringVar(value=f"{self.cfg['min_score']}%"),
            "max_jobs": tk.StringVar(value=str(self.cfg["max_jobs"])), "autostart": tk.BooleanVar(value=self.cfg["autostart"]),
        }
        h = int(self.cfg["interval_h"]); v["interval"].set(next((k for k, x in self.INTERVALS.items() if x == h), f"Every {h} hours"))
        ent = lambda p, key, show=None: ctk.CTkEntry(p, textvariable=v[key], width=260, height=36, corner_radius=8, border_width=1,
                                                      border_color="#D9D2DD", fg_color="#FAF7F9", text_color=NAVY, show=show, font=ctk.CTkFont(FAM, 13))
        def opt(p, key, values):
            if v[key].get() not in values: values = values + [v[key].get()]
            return ctk.CTkOptionMenu(p, variable=v[key], values=values, width=200, height=36, corner_radius=8, fg_color="#FAF7F9",
                                     button_color="#EDE7F2", button_hover_color="#E2DAEA", text_color=NAVY, dropdown_fg_color="white",
                                     dropdown_text_color=NAVY, dropdown_hover_color="#EDE9FE", font=ctk.CTkFont(FAM, 13), dropdown_font=ctk.CTkFont(FAM, 13))
        rows = (("Username", "Shown in the sidebar", lambda p: ent(p, "username")),
                ("AI key", "Free Gemini key from aistudio.google.com, or a Claude key", lambda p: ent(p, "api_key", "•")),
                ("Default job location", "Only keeps jobs in this place or remote. Pick Anywhere for all",
                 lambda p: ctk.CTkComboBox(p, variable=v["location"], values=["Anywhere", "Remote", "Europe", "Hungary", "Morocco", "United States"],
                                           width=200, height=36, corner_radius=8, border_width=1, border_color="#D9D2DD", fg_color="#FAF7F9",
                                           button_color="#EDE7F2", text_color=NAVY, dropdown_fg_color="white", dropdown_text_color=NAVY,
                                           font=ctk.CTkFont(FAM, 13), dropdown_font=ctk.CTkFont(FAM, 13))),
                ("Check for new jobs", "How often the agent searches in the background", lambda p: opt(p, "interval", list(self.INTERVALS))),
                ("Minimum match", "Only jobs scoring at least this get a tailored CV", lambda p: opt(p, "min_score", ["40%", "50%", "60%", "70%", "80%", "90%"])),
                ("Jobs per search", "Most tailored CVs created in one search", lambda p: opt(p, "max_jobs", ["3", "5", "10", "15", "20"])),
                ("Start with Windows", "Open JobAgent minimized and keep searching", lambda p: ctk.CTkSwitch(
                    p, text="", variable=v["autostart"], progress_color="#7B5CF0", width=50)))
        for i, (title, desc, make) in enumerate(rows):
            r = ctk.CTkFrame(sc, fg_color="transparent"); r.grid(row=2 * i, column=0, sticky="ew", padx=14, pady=(6, 6))
            r.grid_columnconfigure(0, weight=1)
            ctk.CTkLabel(r, text=title, font=ctk.CTkFont(FAM, 15, "bold"), text_color=NAVY).grid(row=0, column=0, sticky="w")
            ctk.CTkLabel(r, text=desc, font=ctk.CTkFont(FAM, 12), text_color=GRAY).grid(row=1, column=0, sticky="w")
            make(r).grid(row=0, column=1, rowspan=2, sticky="e")
            ctk.CTkFrame(sc, height=1, fg_color="#ECE7EA", corner_radius=0).grid(row=2 * i + 1, column=0, sticky="ew", padx=14)
        self.save_btn = click_label(card, box_img("Save settings", 400, 42, 8, G1, G2, size=15, bold=False), self.save_cfg)
        self.save_btn.grid(row=1, column=0, pady=(6, 14))
        card.bind("<Configure>", lambda e, c=card: self.fit_save(c))
        return f

    def fit_save(self, card):
        if getattr(self, "_save_pending", None): self.after_cancel(self._save_pending)
        self._save_pending = self.after(150, lambda: self._do_save_fit(card))

    def _do_save_fit(self, card):
        self._save_pending = None
        w = max(200, int(card.winfo_width() / self._get_window_scaling()) - 60)
        if getattr(self.save_btn, "_fit_w", None) != w:
            self.save_btn._fit_w = w
            self.save_btn.configure(width=w, image=box_img("Save settings", w, 42, 8, G1, G2, size=15, bold=False))

    # ================= login popup (drawn inside the main window) =================
    def show_login(self):
        """Dimmed window + centered white card. Everything lives in the main window, so display scaling and
        window positions cannot cut it off."""
        self.update()
        s = self._get_window_scaling()
        W, H = self.winfo_width(), self.winfo_height()            # physical pixels
        try:
            from PIL import ImageGrab
            rx, ry = self.winfo_rootx(), self.winfo_rooty()
            shot = ImageGrab.grab(bbox=(rx, ry, rx + W, ry + H)).convert("RGB")
        except Exception:
            shot = Image.new("RGB", (W, H), (60, 70, 110))
        canvas = Image.blend(shot, Image.new("RGB", (W, H), (5, 14, 50)), 0.55).convert("RGBA")

        k = 3
        cw, ch = int(363 * s), int(337 * s)
        cx, cy = (W - cw) // 2, (H - ch) // 2
        card = Image.new("RGBA", (cw * k, ch * k), (0, 0, 0, 0))
        ImageDraw.Draw(card).rounded_rectangle((0, 0, cw * k - 1, ch * k - 1), radius=int(14 * s * k), fill=(255, 255, 255, 255))
        wave_h = int(74 * s)
        wv = Image.new("L", (cw * k, wave_h * k), 0)
        pts = [(x, (0.20 + 0.34 * math.sin(math.pi * x / (cw * k))) * wave_h * k) for x in range(0, cw * k + 1, 4)]
        ImageDraw.Draw(wv).polygon(pts + [(cw * k, wave_h * k), (0, wave_h * k)], fill=255)
        from PIL import ImageChops
        clip = Image.new("L", (cw * k, ch * k), 0)
        ImageDraw.Draw(clip).rounded_rectangle((0, 0, cw * k - 1, ch * k - 1), radius=int(14 * s * k), fill=255)
        full = Image.new("L", (cw * k, ch * k), 0); full.paste(wv, (0, (ch - wave_h) * k))
        card.paste(hgrad(cw * k, ch * k, G1, G2), (0, 0), ImageChops.multiply(full, clip))
        d = ImageDraw.Draw(card)
        d.ellipse((int(26 * s * k), int(16 * s * k), int(88 * s * k), int(78 * s * k)), fill=(42, 35, 104, 255))
        lg = load_asset("logo"); lh = int(46 * s * k); lg = lg.resize((int(lg.width * lh / lg.height), lh), Image.LANCZOS)
        card.paste(lg, (int(57 * s * k) - lg.width // 2, int(24 * s * k)), lg)
        d.text((int(26 * s * k), int(84 * s * k)), "Welcome to JobAgent", font=pil_font(int(22 * s * k), True), fill=(11, 31, 75, 255))
        d.text((int(27 * s * k), int(124 * s * k)), "Sign in to continue to JobAgent", font=pil_font(int(13 * s * k)), fill=(122, 127, 144, 255))
        d.text((int(27 * s * k), int(150 * s * k)), "Username", font=pil_font(int(13 * s * k), True), fill=(11, 31, 75, 255))
        card = card.resize((cw, ch), Image.LANCZOS)
        canvas.alpha_composite(card, (cx, cy))

        dim = ctk.CTkLabel(self, text="", image=cimg(canvas.convert("RGB"), int(W / s), int(H / s)))
        dim.place(x=0, y=0)
        lx, ly = cx / s, cy / s                                      # card origin in layout units
        name = tk.StringVar()
        entry = ctk.CTkEntry(self, textvariable=name, width=300, height=40, corner_radius=8, border_width=1, border_color="#D9D2DD",
                             fg_color="white", bg_color="white", text_color=NAVY, font=ctk.CTkFont(FAM, 14),
                             placeholder_text="Enter your username")
        entry.place(x=lx + 27, y=ly + 174)
        parts = [dim, entry]
        def go(_=None):
            n = name.get().strip()
            if not n:
                entry.configure(border_color="#E5484D"); return
            self.vars["username"].set(n); self.cfg["username"] = n
            CONFIG.write_text(json.dumps(self.cfg), encoding="utf-8")
            self.set_username(n)
            for p in parts: p.destroy()
        btn = click_label(self, box_img("Continue", 300, 38, 19, G1, G2, size=14, bold=True), go, fg_color="white", bg_color="white")
        btn.place(x=lx + 27, y=ly + 226)
        parts.append(btn)
        entry.bind("<Return>", go)
        self.after(150, entry.focus_force)

    # ================= config =================
    def save_cfg(self):
        v = self.vars
        def pct(s, d):
            try: return int(str(s).replace("%", "").strip())
            except ValueError: return d
        loc = v["location"].get().strip()
        interval = self.INTERVALS.get(v["interval"].get(), None)
        if interval is None:
            digits = "".join(ch for ch in v["interval"].get() if ch.isdigit()); interval = int(digits) if digits else 6
        try: mj = max(1, int(v["max_jobs"].get()))
        except ValueError: mj = 10
        self.cfg.update({"username": v["username"].get().strip(), "api_key": v["api_key"].get().strip(),
                         "location": "" if loc.lower() in ("", "anywhere") else loc, "interval_h": interval,
                         "min_score": pct(v["min_score"].get(), 60), "max_jobs": mj, "autostart": bool(v["autostart"].get())})
        CONFIG.write_text(json.dumps(self.cfg), encoding="utf-8")
        self.apply_key(); self.set_autostart(self.cfg["autostart"]); self.set_username(self.cfg["username"])
        self.say("Settings saved.")

    def apply_key(self):
        """Gemini keys (free, from aistudio.google.com) start with AIza; Claude keys start with sk-ant."""
        key = self.cfg["api_key"].strip()
        os.environ.pop("ANTHROPIC_API_KEY", None); os.environ.pop("GEMINI_API_KEY", None)
        if key.startswith("sk-ant"): os.environ["ANTHROPIC_API_KEY"] = key
        elif key: os.environ["GEMINI_API_KEY"] = key

    def set_autostart(self, on):
        try:
            import winreg
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Run", 0, winreg.KEY_SET_VALUE)
            if on:
                cmd = f'"{sys.executable}" --minimized' if getattr(sys, "frozen", False) else f'"{sys.executable}" "{Path(__file__).resolve()}" --minimized'
                winreg.SetValueEx(key, "JobAgent", 0, winreg.REG_SZ, cmd)
            else:
                try: winreg.DeleteValue(key, "JobAgent")
                except FileNotFoundError: pass
        except ImportError:
            pass

    # ================= queue / state =================
    def say(self, text): self.q.put(("log", text))

    def poll(self):
        try:
            while True:
                kind, payload = self.q.get_nowait()
                if kind == "log": self.add_log(payload)
                elif kind == "refresh": self.refresh_all()
                elif kind == "state": self.set_state(*payload)
                elif kind == "call":
                    fn, box, evt = payload
                    box.append(fn()); evt.set()
        except queue.Empty:
            pass
        self.after(200, self.poll)

    def on_main(self, fn):
        box, evt = [], threading.Event()
        self.q.put(("call", (fn, box, evt))); evt.wait()
        return box[0]

    def running(self):
        return bool(self.worker and self.worker.is_alive() and not self.stop_evt.is_set())

    def set_state(self, kind, sub=""):
        word = {"running": "Active", "searching": "Searching", "stopped": "Stopped"}[kind]
        self.state_text = word
        val, subl = self.cards["status"]
        val.configure(image=gtext(word, 30)); subl.configure(text=sub)
        self.btn_run.configure(text="Stop" if self.running() else "Start", fg_color=DKBLUE if self.running() else PURPLE,
                               hover_color=DKBLUE if self.running() else PURPLE)

    def refresh_all(self):
        jobs = self.jobs()
        ready = ja.PROFILE_PATH.exists()
        cvs = sum(1 for d in ja.OUT.glob("*/cv.pdf")) if ja.OUT.exists() else 0
        v, s = self.cards["cv"]; v.configure(image=gtext(str(cvs), 38)); s.configure(text="CVs saved" if ready else "Load your CV to begin")
        v, s = self.cards["matched"]; v.configure(image=gtext(str(sum(1 for j in jobs if j.get("status") != "skipped")), 38)); s.configure(text="New matches")
        v, s = self.cards["apps"]; v.configure(image=gtext(str(sum(1 for j in jobs if j.get("status") == "applied")), 38)); s.configure(text="Applications sent")
        if not self.running():
            self.set_state("stopped", "Press Start to begin" if ready else "Load your CV first")
        self.render_rows()

    # ================= actions =================
    def load_cv(self):
        path = filedialog.askopenfilename(filetypes=[("CV", "*.pdf *.docx *.txt")])
        if not path: return
        if not self.cfg["api_key"]:
            messagebox.showwarning("AI key", "Enter your Gemini (free) or Claude API key in Settings first."); self.show("SETTINGS"); return
        self.say("Reading CV…")
        def work():
            try:
                ja.parse_cv(path)
                self.cfg["cv_file"] = Path(path).name
                CONFIG.write_text(json.dumps(self.cfg), encoding="utf-8")
                self.q.put(("refresh", None))
            except Exception as e:
                self.say(f"! CV parsing failed: {e}")
        threading.Thread(target=work, daemon=True).start()

    def toggle_agent(self):
        if self.running(): self.stop_agent()
        else: self.start_agent()

    def start_agent(self):
        if not ja.PROFILE_PATH.exists():
            messagebox.showinfo("CV needed", "Load your CV first."); return
        if not self.cfg["api_key"]:
            messagebox.showinfo("AI key needed", "Enter your AI key in Settings first."); self.show("SETTINGS"); return
        self.stop_evt.clear()
        def loop():
            while not self.stop_evt.is_set():
                self.cycle()
                hours = max(1, int(self.cfg["interval_h"]))
                if self.stop_evt.is_set(): break
                self.q.put(("state", ("running", f"Next search in {hours}h")))
                if self.stop_evt.wait(hours * 3600): break
            self.q.put(("state", ("stopped", "Agent is off")))
        self.worker = threading.Thread(target=loop, daemon=True); self.worker.start()
        self.set_state("searching", "Job search in progress")

    def stop_agent(self):
        self.stop_evt.set()
        self.set_state("stopped", "Agent is off")

    def cycle(self):
        if not self.cycle_lock.acquire(blocking=False):
            self.say("A search is already running."); return
        try:
            self.q.put(("state", ("searching", "Job search in progress")))
            new = ja.run(int(self.cfg["min_score"]), int(self.cfg["max_jobs"]), self.cfg["location"] or None)
            self.q.put(("refresh", None))
            if new: self.say(f"✔ {len(new)} new tailored applications ready for review.")
        except Exception as e:
            self.say(f"! Cycle failed: {e}")
        finally:
            self.cycle_lock.release()

    # ================= jobs =================
    def jobs(self): return ja.load_json(ja.JOBS_PATH, [])

    def set_status(self, jid, status):
        data = self.jobs()
        for x in data:
            if x["id"] == jid: x["status"] = status
        ja.JOBS_PATH.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
        self.q.put(("refresh", None))

    def toggle_save(self, j):
        self.set_status(j["id"], "ready" if j.get("status") == "saved" else "saved")

    def open_folder(self, j):
        if hasattr(os, "startfile"): os.startfile(ja.OUT / j["id"])

    def view_job(self, j):
        top = tk.Toplevel(self); top.title(j["title"]); top.configure(bg="white"); top.transient(self)
        s = self._get_window_scaling()                    # keep the window big enough on scaled displays
        tw, th = int(560 * s), int(520 * s)
        top.geometry(f"{tw}x{th}+{self.winfo_rootx() + max(0, (self.winfo_width() - tw) // 2)}+{self.winfo_rooty() + max(0, (self.winfo_height() - th) // 2)}")
        body = ctk.CTkFrame(top, fg_color="white", corner_radius=0); body.pack(fill="both", expand=True, padx=24, pady=20)
        ctk.CTkLabel(body, text=j["title"], font=ctk.CTkFont(FAM, 20, "bold"), text_color=NAVY, wraplength=500, justify="left").pack(anchor="w")
        ctk.CTkLabel(body, text=f"{j['company']}  •  {j['location']}  •  {rel_time(j.get('posted'))}", font=ctk.CTkFont(FAM, 13), text_color=GRAY).pack(anchor="w", pady=(2, 8))
        ctk.CTkLabel(body, text=f"Match {j.get('score', 0)}%", font=ctk.CTkFont(FAM, 16, "bold"), text_color=PURPLE_T).pack(anchor="w")
        info = "\n".join(filter(None, [j.get("reason", ""),
                                       ("Matching: " + ", ".join(j["matching"])) if j.get("matching") else "",
                                       ("Missing: " + ", ".join(j["missing"])) if j.get("missing") else ""]))
        ctk.CTkLabel(body, text=info or "No details saved for this job.", font=ctk.CTkFont(FAM, 13), text_color="#3E4560",
                     wraplength=500, justify="left").pack(anchor="w", pady=10)
        grid = ctk.CTkFrame(body, fg_color="transparent"); grid.pack(side="bottom", fill="x")
        def close_then(fn): return lambda: (top.destroy(), fn())
        btns = (("Apply (pre-fill form)", PURPLE, lambda: self.apply_job(j)),
                ("Open job page", DKBLUE, lambda: webbrowser.open(j["url"])),
                ("Open CV folder", DKBLUE, lambda: self.open_folder(j)),
                ("Mark as applied", "#3B8F5A", lambda: self.set_status(j["id"], "applied")),
                ("Skip this job", "#8A8FA5", lambda: self.set_status(j["id"], "skipped")))
        for i, (t, color, fn) in enumerate(btns):
            b = self.sbtn(grid, t, 240, 36, close_then(fn) if t.startswith(("Apply", "Mark", "Skip")) else fn, color, 13)
            b.grid(row=i // 2, column=i % 2, padx=6, pady=5)

    def apply_job(self, j):
        def work():
            try:
                info = lambda m: self.on_main(lambda: messagebox.showinfo("JobAgent", m))
                ask = lambda m: self.on_main(lambda: messagebox.askyesno("JobAgent", m))
                ja.apply_to(j["id"], info, info, ask)
                done = self.on_main(lambda: messagebox.askyesno("JobAgent", "Did you submit the application?"))
                self.set_status(j["id"], "applied" if done else "ready")
            except Exception as e:
                self.say(f"! Apply failed: {e}")
        threading.Thread(target=work, daemon=True).start()


if __name__ == "__main__":
    App(minimized="--minimized" in sys.argv).mainloop()
